export interface Customer {
  yearsWithMHPCO: number;
  previousContracts: number;
}

export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const FIRST_INSURANCE_SURCHARGE = 0.1;
const PROCESSING_FEE = 5;

export function quote(_customer: Customer, items: Item[]): number {
  const base = items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
  const total = base + base * FIRST_INSURANCE_SURCHARGE + PROCESSING_FEE;
  return Math.ceil(total);
}

